/* A string literal past 255 characters was cut there: the lexer kept
 * the whole literal in its pool but recorded the length of its 256-byte
 * scratch copy, so the program's string was its first 255 bytes (found by
 * s32-sbc, whose programs carry their BASIC source as one literal, and a
 * line of it 386 long).  C11 5.2.4.1 asks for at least 4095.  Lengths,
 * contents, sizeof, concatenation and two equal long literals. */
#include <string.h>

static const char a255[] = "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa";
static const char a256[] = "bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb";
static const char *b1000 = "";
static const char c4095[] = "";
static const char joined[] = "" "";

/* s's first n characters are ch (and, if end, its end follows) */
static int run(const char *s, int n, char ch, int end) {
    for (int i = 0; i < n; i++)
        if (s[i] != ch) return 0;
    return !end || s[n] == 0;
}

static int all(const char *s, int n, char ch) { return run(s, n, ch, 1); }

int main(void) {
    const char *p = "", *q = "";
    if (strlen(a255) != 255 || sizeof a255 != 256 || !all(a255, 255, 'a')) return 1;
    if (strlen(a256) != 256 || sizeof a256 != 257 || !all(a256, 256, 'b')) return 2;
    if (strlen(b1000) != 1000 || !all(b1000, 1000, 'c')) return 3;
    if (strlen(c4095) != 4095 || sizeof c4095 != 4096 || !all(c4095, 4095, 'd')) return 4;
    if (strlen(joined) != 700 || sizeof joined != 701 || !run(joined, 300, 'e', 0) || !all(joined + 300, 400, 'f'))
        return 5;
    if (strlen(p) != 300 || strcmp(p, q) != 0) return 6;
    if (strlen("") != 600) return 7;
    return 0;
}
